import { useCallback, useMemo, useRef, useState, type KeyboardEvent } from 'react';
import { JxChip, JxInputField } from '@jinx-ui/react';

export interface ArticleTagsFieldProps {
  label?: string;
  placeholder?: string;
  defaultValue?: string[];
  value?: string[];
  maxTags?: number;
  disabled?: boolean;
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagsField({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  defaultValue = [],
  value,
  maxTags = 10,
  disabled = false,
  onChange,
}: ArticleTagsFieldProps) {
  const [innerTags, setInnerTags] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');
  const [error, setError] = useState<string | undefined>(undefined);
  const inputRef = useRef<HTMLInputElement>(null);

  const tags = value ?? innerTags;
  const isFull = tags.length >= maxTags;

  const commit = useCallback(
    (next: string[]) => {
      if (value === undefined) setInnerTags(next);
      onChange?.(next);
    },
    [onChange, value],
  );

  const addTag = useCallback(() => {
    const tag = draft.trim().replace(/\s+/g, ' ');
    if (tag.length === 0) return;
    if (tags.some((existing) => existing.toLowerCase() === tag.toLowerCase())) {
      setError(`Тег «${tag}» уже добавлен`);
      return;
    }
    if (isFull) {
      setError(`Можно добавить не больше ${maxTags} тегов`);
      return;
    }
    setError(undefined);
    setDraft('');
    commit([...tags, tag]);
  }, [commit, draft, isFull, maxTags, tags]);

  const removeTag = useCallback(
    (tag: string) => {
      setError(undefined);
      commit(tags.filter((existing) => existing !== tag));
      inputRef.current?.focus();
    },
    [commit, tags],
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag();
      return;
    }
    if (event.key === 'Backspace' && draft.length === 0 && tags.length > 0) {
      event.preventDefault();
      removeTag(tags[tags.length - 1]);
    }
  };

  const counter = useMemo(() => `${tags.length} из ${maxTags}`, [maxTags, tags.length]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', maxWidth: '520px' }}>
      <JxInputField
        ref={inputRef}
        label={label}
        placeholder={isFull ? 'Достигнут предел тегов' : placeholder}
        helperText={`Enter добавляет тег, Backspace удаляет последний. Добавлено ${counter}.`}
        errorText={error}
        value={draft}
        disabled={disabled || isFull}
        onChange={(event) => {
          setDraft(event.target.value);
          if (error) setError(undefined);
        }}
        onKeyDown={handleKeyDown}
        onBlur={addTag}
      />

      {tags.length > 0 ? (
        <ul
          aria-label="Выбранные теги"
          style={{
            display: 'flex',
            flexWrap: 'wrap',
            gap: '8px',
            margin: 0,
            padding: 0,
            listStyle: 'none',
          }}
        >
          {tags.map((tag) => (
            <li key={tag} style={{ display: 'flex', minWidth: 0 }}>
              <JxChip
                active
                removable={!disabled}
                onRemove={disabled ? undefined : () => removeTag(tag)}
                title={tag}
              >
                <span
                  style={{
                    display: 'block',
                    maxWidth: '18ch',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {tag}
                </span>
              </JxChip>
            </li>
          ))}
        </ul>
      ) : (
        <p
          style={{
            margin: 0,
            color: 'var(--jx-text-2)',
            fontFamily: 'var(--jx-font-sans)',
            fontSize: '13px',
          }}
        >
          Тегов пока нет — введите первое ключевое слово, чтобы читатели нашли статью.
        </p>
      )}
    </div>
  );
}

